SELECT
  COUNT(DISTINCT sales.account_id)
  
FROM bigfoot_external_neo.cp_bi_prod_sales__forward_unit_history_fact sales

LEFT JOIN  
fdp_uploads.ds_fkint_cp_santa_hyperlocal_vertical_bu_mapping_2_0 AS hl 
    ON sales.analytic_vertical = hl.analytic_vertical 
    
  WHERE LOWER(sales.status) IN ('in_progress', 'undelivered', 'completed', 'delivered', 'approved', 'shipped', 'ready_to_ship', 'returned', 'return_requested', 'activated')
        AND sales.type  = 'physical'
        AND sales.replacement_for_unit IS NULL
        AND sales.exchange_for_unit IS NULL
        AND sales.is_freebie = FALSE
        AND (sales.marketplace_id IN ('FLIPKART') OR (sales.marketplace_id = 'HYPERLOCAL' AND  hl.analytic_vertical IS NOT NULL))
  AND sales.order_date_key between 20250310 and 20250910 
  AND sales.is_shopsy_order = FALSE
  AND lower(sales.analytic_vertical) IN (
'abexerciser', 'actionfigure', 'adhesive', 'adultdiapers', 'airconditioner', 'aircooler', 'almonds', 'antiseptic', 'appliancecover', 'apron', 'armsleeve', 'artcraftkit', 'artificialflower', 'artificialplant', 'artset', 'attar', 'babyblanket', 'babybodywash', 'babycombogiftset', 'babypillow', 'babyproofing', 'babyrattle', 'babyshampoo', 'babysoap', 'backandabdomensupport', 'backpack', 'badmintonkits', 'badmintonracquets', 'bakingingredientsdecoratives', 'balaclava', 'balloondecoration', 'bar', 'bathandspaaccessory', 'bathroommirror', 'bathroomrackandshelf', 'bathtowel', 'batteries', 'battletoy', 'bedmattress', 'bedsheet', 'bibhankies', 'bikebodycover', 'bikelubricant', 'birthdaycombo', 'blanket', 'bloodpressuremonitor', 'blower', 'boardgame', 'bodyandskinaccessory', 'bodyessentialoil', 'bodylotion', 'bodypainrelief', 'bodyscrub', 'bodyspray', 'bodywash', 'bottle', 'bottleaccessory', 'boycasualshoemisc', 'boycomboset', 'boyethnicset', 'boyinnerwear', 'boyjean', 'boyshirt', 'boyshort', 'boysportsshoe', 'boytrackpant', 'boytshirt', 'broomandbrush', 'brushapplicator', 'bulb', 'cabledropclips', 'calculator', 'cameratripod', 'candiesmouthfresheners', 'carairfreshener', 'carbodycover', 'cardholders', 'carlightbulb', 'carmobileholder', 'carpetrug', 'carpolish', 'carpressurewasher', 'carriercuddler', 'carstickeranddecal', 'carwasherliquid', 'cashews', 'ceilinglamp', 'celltapeanddispenser', 'childrensbooks', 'chocolates', 'chopper', 'cleaningcloth', 'cleaningglove', 'clothclip', 'clothdryerstand', 'cnflaceup', 'cnfsandal', 'cnfslipon', 'coffee', 'coinbank', 'colanderandsieve', 'collapsiblewardrobe', 'collarandharness', 'comboandkit', 'compact', 'computerglassframes', 'concealer', 'condiments', 'condimentset', 'conditioner', 'condom', 'container', 'cookwareset', 'cribtoyplaygym', 'cricketball', 'cupandsaucer', 'curtainaccessories', 'cuttingboard', 'cyclinglight', 'dairynotebook', 'dates', 'decorwallshelf', 'deitydress', 'delayspray', 'deodorantformen', 'deodorantforwomen', 'des